"""
setup_phase1.py — RiskLens v2
================================
DROP THIS FILE into your risklens-v2 project root (same folder as server.py).
Then run ONE command:

    python setup_phase1.py

What it does:
  - Creates every new Phase 1 file with the correct code already inside it
  - If a file already exists it REPLACES the old code with the new code
  - Prints exactly which files were created vs replaced so you know what changed
  - Existing files NOT in this list (core/, tools/, server.py etc.) are untouched

After it finishes:
    pip install fastapi "uvicorn[standard]" supabase "python-jose[cryptography]" cryptography tzdata
    uvicorn api.main:app --port 8000 --reload
"""

import os
import sys


def main():
    root = os.path.dirname(os.path.abspath(__file__))
    created, replaced, errors = [], [], []

    for rel_path, content in _FILES.items():
        full_path = os.path.join(root, rel_path)

        # Always create parent directories
        os.makedirs(os.path.dirname(full_path), exist_ok=True)

        already_existed = os.path.exists(full_path)

        try:
            with open(full_path, "w", encoding="utf-8") as f:
                f.write(content)

            if already_existed:
                replaced.append(rel_path)
                print(f"  🔄 replaced  {rel_path}")
            else:
                created.append(rel_path)
                print(f"  ✅ created   {rel_path}")

        except Exception as e:
            errors.append(f"{rel_path}: {e}")
            print(f"  ❌ FAILED    {rel_path}: {e}")

    print(f"\n{'='*55}")
    print(f"  ✅ Created  : {len(created)} files")
    print(f"  🔄 Replaced : {len(replaced)} files")
    print(f"  ❌ Errors   : {len(errors)} files")
    print(f"{'='*55}")

    if errors:
        print("\nFailed files:")
        for e in errors:
            print(f"  {e}")
        sys.exit(1)

    print("\n✅ All done! Next steps:")
    print("")
    print('  1. Install new dependencies:')
    print('     pip install fastapi "uvicorn[standard]" supabase "python-jose[cryptography]" cryptography tzdata')
    print("")
    print("  2. Fill in your .env file (copy from .env.example):")
    print("     SUPABASE_URL, SUPABASE_ANON_KEY, SUPABASE_SERVICE_ROLE_KEY,")
    print("     SUPABASE_JWT_SECRET, ENCRYPTION_KEY, PAYSTACK_SECRET_KEY")
    print("")
    print("  3. Run the SQL migration in Supabase SQL Editor:")
    print("     db/migrations/001_initial_schema.sql")
    print("")
    print("  4. Start the API server:")
    print("     uvicorn api.main:app --port 8000 --reload")


# ── Embedded file contents ────────────────────────────────────────────────────
# Every file below will be written (or overwritten) to its exact path.
# DO NOT edit below this line unless you know what you are doing.
_FILES = {}

_FILES['db/__init__.py'] = '# db/__init__.py\n'

_FILES['db/client.py'] = '"""\ndb/client.py — RiskLens v2\n============================\nSupabase client singleton.\n\nTwo clients are maintained:\n  - anon_client  — uses the ANON key; respects Row Level Security.\n                   Used for all user-authenticated operations where\n                   the JWT is passed in the request header.\n  - admin_client — uses the SERVICE ROLE key; bypasses RLS.\n                   Used ONLY for server-side operations (webhook\n                   handlers, background jobs, admin actions).\n                   Never expose this client to user-controlled input.\n\nBoth clients are created once at import time and reused. This avoids\nthe overhead of creating a new httpx connection pool per request.\n"""\n\nimport os\nfrom functools import lru_cache\nfrom supabase import create_client, Client\n\n_SUPABASE_URL           = os.environ["SUPABASE_URL"]\n_SUPABASE_ANON_KEY      = os.environ["SUPABASE_ANON_KEY"]\n_SUPABASE_SERVICE_KEY   = os.environ["SUPABASE_SERVICE_ROLE_KEY"]\n\n\n@lru_cache(maxsize=1)\ndef get_anon_client() -> Client:\n    """\n    Returns the singleton anon (public) Supabase client.\n    Respects RLS — all operations run as the requesting user.\n    Pass the user\'s JWT via: client.auth.set_session(access_token, refresh_token)\n    or use the admin client and filter by user_id explicitly.\n    """\n    return create_client(_SUPABASE_URL, _SUPABASE_ANON_KEY)\n\n\n@lru_cache(maxsize=1)\ndef get_admin_client() -> Client:\n    """\n    Returns the singleton admin (service role) Supabase client.\n    Bypasses RLS — use only for trusted server-side operations.\n    NEVER use this for anything driven by user input without\n    explicit user_id filtering.\n    """\n    return create_client(_SUPABASE_URL, _SUPABASE_SERVICE_KEY)\n\n\n# Convenience aliases used throughout the codebase\nsupabase: Client      = None   # populated on first call to get_anon_client()\nadmin_db: Client      = None   # populated on first call to get_admin_client()\n\n\ndef init_clients() -> None:\n    """\n    Called once from api/main.py startup to warm both clients.\n    Avoids cold-start latency on the first real request.\n    """\n    global supabase, admin_db\n    supabase = get_anon_client()\n    admin_db = get_admin_client()\n'

_FILES['db/migrations/001_initial_schema.sql'] = '-- ============================================================\n-- RiskLens v2 — Full Database Schema\n-- Run this ONCE in the Supabase SQL Editor (Dashboard → SQL Editor)\n-- ============================================================\n\n\n-- ── SHARED TRIGGER FUNCTION ──────────────────────────────────\nCREATE OR REPLACE FUNCTION update_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN NEW.updated_at = NOW(); RETURN NEW; END;\n$$ LANGUAGE plpgsql;\n\n\n-- ── 1. USERS ─────────────────────────────────────────────────\n-- Extends Supabase Auth (auth.users). Never store passwords here.\n\nCREATE TABLE IF NOT EXISTS public.users (\n    id              UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n    email           TEXT UNIQUE NOT NULL,\n    full_name       TEXT NOT NULL DEFAULT \'\',\n\n    -- User\'s own AI provider (they bring their own key)\n    ai_provider     TEXT CHECK (ai_provider IN (\'claude\', \'grok\', \'gemini\')),\n    ai_api_key_enc  TEXT,        -- AES-256 encrypted — NEVER stored plain\n    ai_model        TEXT,        -- e.g. \'claude-sonnet-4-6\', \'gemini-2.0-flash\'\n\n    -- Timezone for per-user daily free-tier reset\n    timezone        TEXT NOT NULL DEFAULT \'UTC\',\n\n    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n    last_active_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\nCREATE TRIGGER users_updated_at\n    BEFORE UPDATE ON public.users\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at();\n\n\n-- ── 2. SUBSCRIPTIONS ─────────────────────────────────────────\n-- One row per user. Auto-created as \'free\' on registration.\n\nCREATE TABLE IF NOT EXISTS public.subscriptions (\n    id                          UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    user_id                     UUID NOT NULL UNIQUE\n                                    REFERENCES public.users(id) ON DELETE CASCADE,\n    plan                        TEXT NOT NULL DEFAULT \'free\'\n                                    CHECK (plan IN (\'free\', \'pro\', \'business\')),\n    status                      TEXT NOT NULL DEFAULT \'active\'\n                                    CHECK (status IN (\'active\', \'cancelled\', \'expired\', \'past_due\')),\n\n    -- Paystack identifiers (null until user upgrades)\n    paystack_customer_id        TEXT,\n    paystack_subscription_id    TEXT,\n    paystack_subscription_code  TEXT,\n    paystack_plan_code          TEXT,\n\n    -- Billing window (null on free plan)\n    current_period_start        TIMESTAMPTZ,\n    current_period_end          TIMESTAMPTZ,\n\n    -- Business plan only\n    team_seats                  INTEGER NOT NULL DEFAULT 1,\n    team_owner_id               UUID REFERENCES public.users(id) ON DELETE SET NULL,\n\n    created_at                  TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n    updated_at                  TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\nCREATE TRIGGER subscriptions_updated_at\n    BEFORE UPDATE ON public.subscriptions\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at();\n\n\n-- ── 3. USAGE_LOGS ────────────────────────────────────────────\n-- One row per tool run. Usage date is stored in user\'s timezone\n-- so the daily free limit resets at midnight in their local time.\n\nCREATE TABLE IF NOT EXISTS public.usage_logs (\n    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    user_id     UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n    tool_name   TEXT NOT NULL,\n    ticker      TEXT,\n    -- Date computed server-side as: (NOW() AT TIME ZONE user.timezone)::DATE\n    usage_date  DATE NOT NULL,\n    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_usage_user_date ON public.usage_logs (user_id, usage_date);\nCREATE INDEX IF NOT EXISTS idx_usage_tool      ON public.usage_logs (tool_name);\n\n\n-- ── 4. ANALYSES ──────────────────────────────────────────────\n-- Full record of every tool run: raw structured output + AI explanation.\n\nCREATE TABLE IF NOT EXISTS public.analyses (\n    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    user_id             UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n\n    ticker              TEXT NOT NULL,\n    tool_name           TEXT NOT NULL,\n    tool_params         JSONB NOT NULL DEFAULT \'{}\',\n\n    -- Raw structured output from the tool (can be large JSONB)\n    tool_output         JSONB,\n\n    -- AI natural language interpretation (populated in Phase 2)\n    ai_interpretation   TEXT,\n    ai_provider         TEXT,\n    ai_model            TEXT,\n\n    status              TEXT NOT NULL DEFAULT \'pending\'\n                            CHECK (status IN (\'pending\', \'processing\', \'completed\', \'failed\')),\n    failure_reason      TEXT,\n    elapsed_seconds     FLOAT,\n\n    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_analyses_user   ON public.analyses (user_id, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_analyses_ticker ON public.analyses (ticker);\nCREATE INDEX IF NOT EXISTS idx_analyses_tool   ON public.analyses (tool_name);\nCREATE INDEX IF NOT EXISTS idx_analyses_status ON public.analyses (status);\n\nCREATE TRIGGER analyses_updated_at\n    BEFORE UPDATE ON public.analyses\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at();\n\n\n-- ── 5. CONVERSATIONS ─────────────────────────────────────────\n-- A chat thread. Can be linked to an analysis for context.\n\nCREATE TABLE IF NOT EXISTS public.conversations (\n    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    user_id         UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n    analysis_id     UUID REFERENCES public.analyses(id) ON DELETE SET NULL,\n    title           TEXT,\n    ticker          TEXT,\n    message_count   INTEGER NOT NULL DEFAULT 0,\n    last_message_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_conversations_user     ON public.conversations (user_id, last_message_at DESC);\nCREATE INDEX IF NOT EXISTS idx_conversations_analysis ON public.conversations (analysis_id);\n\nCREATE TRIGGER conversations_updated_at\n    BEFORE UPDATE ON public.conversations\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at();\n\n\n-- ── 6. MESSAGES ──────────────────────────────────────────────\n\nCREATE TABLE IF NOT EXISTS public.messages (\n    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    conversation_id         UUID NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE,\n    user_id                 UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n    role                    TEXT NOT NULL CHECK (role IN (\'user\', \'assistant\', \'system\')),\n    content                 TEXT NOT NULL,\n    triggered_analysis_id   UUID REFERENCES public.analyses(id) ON DELETE SET NULL,\n    tool_name               TEXT,\n    tool_params             JSONB DEFAULT \'{}\',\n    token_count             INTEGER,\n    created_at              TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_messages_conversation\n    ON public.messages (conversation_id, created_at ASC);\nCREATE INDEX IF NOT EXISTS idx_messages_user ON public.messages (user_id);\n\n\n-- ── 7. AUTO-UPDATE conversation counters on new message ──────\n\nCREATE OR REPLACE FUNCTION sync_conversation_on_message()\nRETURNS TRIGGER AS $$\nBEGIN\n    UPDATE public.conversations\n    SET message_count   = message_count + 1,\n        last_message_at = NEW.created_at,\n        updated_at      = NOW()\n    WHERE id = NEW.conversation_id;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE OR REPLACE TRIGGER messages_sync_conversation\n    AFTER INSERT ON public.messages\n    FOR EACH ROW EXECUTE FUNCTION sync_conversation_on_message();\n\n\n-- ── 8. AUTO-CREATE subscription on signup ────────────────────\n\nCREATE OR REPLACE FUNCTION create_free_subscription()\nRETURNS TRIGGER AS $$\nBEGIN\n    INSERT INTO public.subscriptions (user_id, plan, status)\n    VALUES (NEW.id, \'free\', \'active\')\n    ON CONFLICT (user_id) DO NOTHING;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE OR REPLACE TRIGGER users_create_subscription\n    AFTER INSERT ON public.users\n    FOR EACH ROW EXECUTE FUNCTION create_free_subscription();\n\n\n-- ── 9. AUTO-CREATE public.users from auth.users ──────────────\n-- When Supabase Auth creates a user, mirror the row here.\n-- full_name comes from optional signup metadata.\n\nCREATE OR REPLACE FUNCTION public.handle_new_auth_user()\nRETURNS TRIGGER AS $$\nBEGIN\n    INSERT INTO public.users (id, email, full_name)\n    VALUES (\n        NEW.id,\n        NEW.email,\n        COALESCE(NEW.raw_user_meta_data->>\'full_name\', \'\')\n    )\n    ON CONFLICT (id) DO NOTHING;\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nCREATE OR REPLACE TRIGGER on_auth_user_created\n    AFTER INSERT ON auth.users\n    FOR EACH ROW EXECUTE FUNCTION public.handle_new_auth_user();\n\n\n-- ── 10. ROW LEVEL SECURITY ───────────────────────────────────\n\nALTER TABLE public.users          ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.subscriptions  ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.usage_logs     ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.analyses       ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.conversations  ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.messages       ENABLE ROW LEVEL SECURITY;\n\n-- Users\nCREATE POLICY "users_select_own"\n    ON public.users FOR SELECT USING (auth.uid() = id);\nCREATE POLICY "users_update_own"\n    ON public.users FOR UPDATE USING (auth.uid() = id);\n\n-- Subscriptions\nCREATE POLICY "subscriptions_select_own"\n    ON public.subscriptions FOR SELECT USING (auth.uid() = user_id);\n\n-- Usage logs\nCREATE POLICY "usage_select_own"\n    ON public.usage_logs FOR SELECT USING (auth.uid() = user_id);\nCREATE POLICY "usage_insert_own"\n    ON public.usage_logs FOR INSERT WITH CHECK (auth.uid() = user_id);\n\n-- Analyses\nCREATE POLICY "analyses_select_own"\n    ON public.analyses FOR SELECT USING (auth.uid() = user_id);\nCREATE POLICY "analyses_insert_own"\n    ON public.analyses FOR INSERT WITH CHECK (auth.uid() = user_id);\nCREATE POLICY "analyses_update_own"\n    ON public.analyses FOR UPDATE USING (auth.uid() = user_id);\n\n-- Conversations\nCREATE POLICY "conversations_all_own"\n    ON public.conversations FOR ALL USING (auth.uid() = user_id);\n\n-- Messages\nCREATE POLICY "messages_all_own"\n    ON public.messages FOR ALL USING (auth.uid() = user_id);\n'

_FILES['services/__init__.py'] = '# services/__init__.py\n'

_FILES['services/encryption_service.py'] = '"""\nservices/encryption_service.py — RiskLens v2\n==============================================\nAES-256 encryption for user AI API keys.\n\nWe use Fernet symmetric encryption from the `cryptography` library.\nFernet = AES-128-CBC + HMAC-SHA256, with authenticated encryption —\nit guarantees both confidentiality AND integrity. The key is 32 random\nbytes (256 bits) base64-encoded, stored in the ENCRYPTION_KEY env var.\n\nKey generation (run once, store in Render env):\n    python -c "from cryptography.fernet import Fernet; print(Fernet.generate_key().decode())"\n\nWhy not AES-256-GCM directly: Fernet is simpler to use correctly,\nhandles IV/nonce generation and authentication tag automatically,\nand is battle-tested. For key storage in an env var, this is\nthe right level of complexity.\n\nSecurity model:\n  - ENCRYPTION_KEY never touches the DB\n  - Encrypted API keys (ai_api_key_enc) are stored in Supabase\n  - Decryption only happens server-side, in memory, when a request\n    needs to call the user\'s AI provider\n  - Even if the Supabase DB is leaked, API keys are not exposed\n"""\n\nimport os\nfrom typing import Optional\nfrom cryptography.fernet import Fernet, InvalidToken\n\n_RAW_KEY = os.environ.get("ENCRYPTION_KEY", "")\n\nif not _RAW_KEY:\n    raise RuntimeError(\n        "ENCRYPTION_KEY environment variable is not set. "\n        "Generate one with: python -c \\"from cryptography.fernet import Fernet; "\n        "print(Fernet.generate_key().decode())\\""\n    )\n\ntry:\n    _FERNET = Fernet(_RAW_KEY.encode() if isinstance(_RAW_KEY, str) else _RAW_KEY)\nexcept Exception as e:\n    raise RuntimeError(\n        f"ENCRYPTION_KEY is invalid: {e}. "\n        "It must be a 32-byte URL-safe base64-encoded string."\n    ) from e\n\n\ndef encrypt_api_key(plaintext_key: str) -> str:\n    """\n    Encrypt a plaintext API key and return the encrypted string\n    (URL-safe base64, safe to store in a TEXT column).\n\n    Args:\n        plaintext_key: The raw API key from the user (e.g. \'sk-ant-...\')\n\n    Returns:\n        Encrypted token as a UTF-8 string, safe for DB storage.\n    """\n    if not plaintext_key or not plaintext_key.strip():\n        raise ValueError("API key cannot be empty")\n    return _FERNET.encrypt(plaintext_key.strip().encode()).decode()\n\n\ndef decrypt_api_key(encrypted_key: str) -> str:\n    """\n    Decrypt an encrypted API key back to plaintext.\n\n    Args:\n        encrypted_key: The value stored in ai_api_key_enc column.\n\n    Returns:\n        The original plaintext API key.\n\n    Raises:\n        ValueError: If decryption fails (key was tampered or wrong env key).\n    """\n    if not encrypted_key:\n        raise ValueError("No encrypted key provided")\n    try:\n        return _FERNET.decrypt(encrypted_key.encode()).decode()\n    except InvalidToken as e:\n        raise ValueError(\n            "Failed to decrypt API key — the ENCRYPTION_KEY may have changed "\n            "or the stored value is corrupted."\n        ) from e\n\n\ndef has_valid_key(encrypted_key: Optional[str]) -> bool:\n    """\n    Returns True if the stored encrypted key is non-empty and decryptable.\n    Used for checking whether a user has connected their AI.\n    Does NOT return the decrypted value — use decrypt_api_key() for that.\n    """\n    if not encrypted_key:\n        return False\n    try:\n        _FERNET.decrypt(encrypted_key.encode())\n        return True\n    except InvalidToken:\n        return False\n'

_FILES['services/usage_service.py'] = '"""\nservices/usage_service.py — RiskLens v2\n=========================================\nDaily usage limit enforcement with per-user timezone reset.\n\nFree tier: 2 analyses per day, reset at midnight in the USER\'s timezone.\nThis means a user in Lagos (WAT, UTC+1) gets a fresh 2 analyses at\nmidnight Lagos time — not midnight UTC. This makes the free tier feel\nfair and personal rather than arbitrary.\n\nHow timezone-aware daily limits work:\n  1. User\'s timezone is stored in public.users.timezone (default \'UTC\')\n  2. On every tool run, we compute the user\'s local date:\n       local_date = datetime.now(ZoneInfo(user.timezone)).date()\n  3. We count usage_logs rows where user_id = X AND usage_date = local_date\n  4. If count >= FREE_DAILY_LIMIT, we reject the request\n\nPlan limits:\n  Free     → 2 analyses/day, resets at midnight local time\n  Pro      → unlimited\n  Business → unlimited (+ team features)\n"""\n\nimport asyncio\nfrom datetime import datetime, date\nfrom typing import Optional\nfrom zoneinfo import ZoneInfo, ZoneInfoNotFoundError\n\nFREE_DAILY_LIMIT = 2\n\n\ndef _get_user_local_date(timezone_str: str) -> date:\n    """\n    Returns today\'s date in the user\'s timezone.\n    Falls back to UTC if the timezone string is invalid.\n    """\n    try:\n        tz = ZoneInfo(timezone_str or "UTC")\n    except ZoneInfoNotFoundError:\n        tz = ZoneInfo("UTC")\n    return datetime.now(tz).date()\n\n\nasync def get_today_usage_count(user_id: str, user_timezone: str) -> int:\n    """\n    Returns how many analyses the user has run today (in their timezone).\n    Queries the usage_logs table.\n    """\n    from db.client import get_admin_client\n\n    local_date = _get_user_local_date(user_timezone)\n    date_str = local_date.isoformat()   # e.g. \'2025-06-26\'\n\n    def _query():\n        client = get_admin_client()\n        result = (\n            client.table("usage_logs")\n            .select("id", count="exact")\n            .eq("user_id", user_id)\n            .eq("usage_date", date_str)\n            .execute()\n        )\n        return result.count or 0\n\n    return await asyncio.to_thread(_query)\n\n\nasync def check_usage_allowed(\n    user_id: str,\n    user_timezone: str,\n    plan: str,\n) -> tuple[bool, Optional[str]]:\n    """\n    Returns (allowed: bool, error_message: Optional[str]).\n\n    Called before every tool run. Pro and Business users are always\n    allowed. Free users are checked against the daily limit.\n\n    Returns:\n        (True, None)            — allowed, proceed\n        (False, error_message)  — blocked, show error to user\n    """\n    if plan in ("pro", "business"):\n        return True, None\n\n    count = await get_today_usage_count(user_id, user_timezone)\n\n    if count >= FREE_DAILY_LIMIT:\n        tz_label = user_timezone or "UTC"\n        return False, (\n            f"Free tier limit reached: {count}/{FREE_DAILY_LIMIT} analyses used today "\n            f"(resets at midnight {tz_label}). "\n            "Upgrade to Pro for unlimited analyses."\n        )\n\n    return True, None\n\n\nasync def log_usage(user_id: str, user_timezone: str, tool_name: str, ticker: str) -> None:\n    """\n    Inserts a usage_log row for this tool run.\n    Called AFTER a successful tool run — failed runs don\'t count.\n    """\n    from db.client import get_admin_client\n\n    local_date = _get_user_local_date(user_timezone)\n\n    def _insert():\n        client = get_admin_client()\n        client.table("usage_logs").insert({\n            "user_id":    user_id,\n            "tool_name":  tool_name,\n            "ticker":     ticker.upper() if ticker else None,\n            "usage_date": local_date.isoformat(),\n        }).execute()\n\n    await asyncio.to_thread(_insert)\n\n\nasync def get_usage_summary(user_id: str, user_timezone: str, plan: str) -> dict:\n    """\n    Returns a usage summary dict for the /subscriptions/me endpoint.\n    Shows today\'s usage and remaining analyses.\n    """\n    count = await get_today_usage_count(user_id, user_timezone)\n    local_date = _get_user_local_date(user_timezone)\n\n    if plan in ("pro", "business"):\n        return {\n            "plan":           plan,\n            "today_count":    count,\n            "daily_limit":    None,         # unlimited\n            "remaining":      None,\n            "reset_date":     local_date.isoformat(),\n            "reset_timezone": user_timezone or "UTC",\n        }\n\n    remaining = max(0, FREE_DAILY_LIMIT - count)\n    return {\n        "plan":           "free",\n        "today_count":    count,\n        "daily_limit":    FREE_DAILY_LIMIT,\n        "remaining":      remaining,\n        "reset_date":     local_date.isoformat(),\n        "reset_timezone": user_timezone or "UTC",\n    }\n'

_FILES['services/analysis_service.py'] = '"""\nservices/analysis_service.py — RiskLens v2\n============================================\nOrchestrates tool execution, result persistence, and usage logging.\n\nArchitecture\n------------\nThis service sits between the FastAPI route handlers and the existing\ntool pipeline functions. It does NOT import from FastMCP or touch the\nMCP server — it calls the core pipeline functions directly, just as the\nMCP tool wrappers do. Both the MCP server and REST API share the same\nUpstash Redis cache, so a result cached by a Claude Desktop call is\ninstantly available to a REST API caller for the same ticker/tool.\n\nTool registry\n-------------\nEach tool entry maps a tool_name string to:\n  - fn      : the async pipeline function to call\n  - params  : which kwargs to pass from the user\'s request\n  - plan    : minimum plan required (\'free\' = everyone)\n\nThe private pipeline functions (_run_pipeline etc.) are intentionally\ncalled directly. Python does not enforce name-mangling on _ prefixes\nfor module-level functions — this is an established pattern when wrapping\ninternal logic for a different transport layer.\n\nSerialisation\n-------------\nPydantic models are serialised via .model_dump_json() → json.loads()\nto guarantee all enum values and datetimes are JSON-native before\nstorage in Supabase\'s JSONB column.\n"""\n\nimport asyncio\nimport json\nimport time\nimport uuid\nfrom typing import Any, Optional\n\nfrom pydantic import BaseModel\n\n\n# ---------------------------------------------------------------------------\n# Tool registry\n# ---------------------------------------------------------------------------\n\ndef _load_tool_registry() -> dict:\n    """\n    Lazily import pipeline functions to avoid circular imports at module load.\n    Each tool entry:\n      fn        — async callable that runs the analysis\n      param_map — maps request param names to pipeline kwargs\n      min_plan  — minimum subscription plan required\n    """\n    from tools.compare_filings   import _run_pipeline          as _compare\n    from tools.executive_report  import _run_report_pipeline   as _report\n    from tools.risk_categorizer  import _run_categorizer_pipeline as _categorize\n    from tools.risk_trends       import _run_trends_pipeline   as _trends\n    from core.eight_k            import analyze_8k_filings\n    from core.proxy              import analyze_proxy_filing\n    from core.insider            import analyze_insider_filings\n    from core.ownership          import analyze_ownership_filings\n\n    # Thin async wrappers that normalise return types to plain dicts\n    async def compare(p):\n        result = await _compare(p["ticker"], p.get("form_type", "10-Q"))\n        return _to_dict(result)\n\n    async def report(p):\n        result = await _report(p["ticker"], p.get("form_type", "10-K"))\n        return _to_dict(result)\n\n    async def categorize(p):\n        result = await _categorize(p["ticker"], p.get("form_type", "10-K"))\n        return _to_dict(result)\n\n    async def trends(p):\n        result = await _trends(\n            p["ticker"],\n            p.get("form_type", "10-K"),\n            int(p.get("n_filings", 4)),\n        )\n        return _to_dict(result)\n\n    async def eight_k(p):\n        result = await analyze_8k_filings(\n            p["ticker"], n_filings=int(p.get("n_filings", 5))\n        )\n        result.pop("from_cache", None)\n        return result\n\n    async def proxy(p):\n        result = await analyze_proxy_filing(p["ticker"])\n        result.pop("from_cache", None)\n        return result\n\n    async def insider(p):\n        result = await analyze_insider_filings(\n            p["ticker"], n_filings=int(p.get("n_filings", 10))\n        )\n        result.pop("from_cache", None)\n        return result\n\n    async def ownership(p):\n        result = await analyze_ownership_filings(\n            p["ticker"], n_filings=int(p.get("n_filings", 6))\n        )\n        result.pop("from_cache", None)\n        return result\n\n    return {\n        "compare_filings": {\n            "fn": compare,\n            "description": "Compare two most recent filings (Risk Factors + MD&A delta)",\n            "min_plan": "free",\n        },\n        "generate_executive_report": {\n            "fn": report,\n            "description": "Human-readable analyst report from SEC filing",\n            "min_plan": "free",\n        },\n        "categorize_risks": {\n            "fn": categorize,\n            "description": "Classify Risk Factors into 10 standardised domains",\n            "min_plan": "free",\n        },\n        "analyze_risk_trends": {\n            "fn": trends,\n            "description": "Multi-filing risk trajectory analysis",\n            "min_plan": "pro",          # heavier pipeline — pro only\n        },\n        "analyze_8k_events": {\n            "fn": eight_k,\n            "description": "Real-time material event intelligence from 8-K filings",\n            "min_plan": "free",\n        },\n        "analyze_proxy": {\n            "fn": proxy,\n            "description": "Governance & compensation risk from DEF 14A proxy",\n            "min_plan": "pro",\n        },\n        "analyze_insider_activity": {\n            "fn": insider,\n            "description": "Insider buying/selling trends from Form 4 filings",\n            "min_plan": "pro",\n        },\n        "analyze_ownership": {\n            "fn": ownership,\n            "description": "Activist & institutional ownership from 13D/13G/13F",\n            "min_plan": "pro",\n        },\n    }\n\n\n_REGISTRY: Optional[dict] = None\n\n\ndef get_registry() -> dict:\n    global _REGISTRY\n    if _REGISTRY is None:\n        _REGISTRY = _load_tool_registry()\n    return _REGISTRY\n\n\ndef list_tools(plan: str) -> list[dict]:\n    """Returns tool metadata visible to the user based on their plan."""\n    registry = get_registry()\n    _PLAN_ORDER = {"free": 0, "pro": 1, "business": 2}\n    user_level = _PLAN_ORDER.get(plan, 0)\n    return [\n        {\n            "tool_name":   name,\n            "description": meta["description"],\n            "available":   _PLAN_ORDER.get(meta["min_plan"], 0) <= user_level,\n            "min_plan":    meta["min_plan"],\n        }\n        for name, meta in registry.items()\n    ]\n\n\n# ---------------------------------------------------------------------------\n# Main entry point\n# ---------------------------------------------------------------------------\n\nasync def run_analysis(\n    user_id:       str,\n    tool_name:     str,\n    ticker:        str,\n    params:        dict,\n    plan:          str,\n    user_timezone: str,\n) -> dict:\n    """\n    Full analysis lifecycle:\n      1. Validate tool name and plan access\n      2. Create a \'pending\' analysis record\n      3. Run the tool pipeline (with Upstash cache)\n      4. Update the record with results\n      5. Log usage (on success only)\n\n    Returns a dict with \'analysis_id\' and the full tool output.\n    Raises ValueError for validation failures.\n    Raises PermissionError for plan restrictions.\n    """\n    registry = get_registry()\n\n    # ── Validation ───────────────────────────────────────────────────────────\n    if tool_name not in registry:\n        raise ValueError(\n            f"Unknown tool: \'{tool_name}\'. "\n            f"Valid options: {list(registry.keys())}"\n        )\n\n    tool_meta = registry[tool_name]\n    _PLAN_ORDER = {"free": 0, "pro": 1, "business": 2}\n    if _PLAN_ORDER.get(plan, 0) < _PLAN_ORDER.get(tool_meta["min_plan"], 0):\n        raise PermissionError(\n            f"\'{tool_name}\' requires a {tool_meta[\'min_plan\'].upper()} plan. "\n            f"Your current plan is {plan.upper()}. Upgrade to access this tool."\n        )\n\n    ticker = ticker.upper().strip()\n    if not ticker:\n        raise ValueError("ticker is required")\n\n    # ── Create analysis record (status=processing) ────────────────────────\n    analysis_id = str(uuid.uuid4())\n    tool_params = {"ticker": ticker, **params}\n\n    analysis_record = {\n        "id":          analysis_id,\n        "user_id":     user_id,\n        "ticker":      ticker,\n        "tool_name":   tool_name,\n        "tool_params": tool_params,\n        "status":      "processing",\n    }\n\n    await _db_insert("analyses", analysis_record)\n\n    # ── Run the pipeline ──────────────────────────────────────────────────\n    start = time.monotonic()\n    tool_output = None\n    success = False\n    failure_reason = None\n\n    try:\n        tool_output = await tool_meta["fn"](tool_params)\n        success = tool_output.get("pipeline_success", True)\n        if not success:\n            failure_reason = tool_output.get("failure_reason", "Pipeline returned failure")\n    except Exception as exc:\n        failure_reason = f"Unexpected error during {tool_name}: {type(exc).__name__}: {exc}"\n        success = False\n\n    elapsed = round(time.monotonic() - start, 2)\n\n    # ── Update analysis record ────────────────────────────────────────────\n    update_payload: dict[str, Any] = {\n        "status":          "completed" if success else "failed",\n        "elapsed_seconds": elapsed,\n    }\n    if tool_output:\n        update_payload["tool_output"] = _make_json_safe(tool_output)\n    if failure_reason:\n        update_payload["failure_reason"] = failure_reason\n\n    await _db_update("analyses", analysis_id, update_payload)\n\n    # ── Log usage (only on success) ───────────────────────────────────────\n    if success:\n        from services.usage_service import log_usage\n        await log_usage(user_id, user_timezone, tool_name, ticker)\n\n    return {\n        "analysis_id":     analysis_id,\n        "ticker":          ticker,\n        "tool_name":       tool_name,\n        "status":          update_payload["status"],\n        "pipeline_success": success,\n        "failure_reason":  failure_reason,\n        "elapsed_seconds": elapsed,\n        "tool_output":     tool_output,\n    }\n\n\n# ---------------------------------------------------------------------------\n# DB helpers — all Supabase calls run in a thread to avoid blocking the\n# asyncio event loop (supabase-py uses synchronous httpx internally)\n# ---------------------------------------------------------------------------\n\nasync def _db_insert(table: str, data: dict) -> None:\n    def _op():\n        from db.client import get_admin_client\n        get_admin_client().table(table).insert(data).execute()\n    await asyncio.to_thread(_op)\n\n\nasync def _db_update(table: str, record_id: str, data: dict) -> None:\n    def _op():\n        from db.client import get_admin_client\n        get_admin_client().table(table).update(data).eq("id", record_id).execute()\n    await asyncio.to_thread(_op)\n\n\nasync def get_analysis_by_id(analysis_id: str, user_id: str) -> Optional[dict]:\n    """Fetch a single analysis record. Returns None if not found or wrong user."""\n    def _op():\n        from db.client import get_admin_client\n        result = (\n            get_admin_client()\n            .table("analyses")\n            .select("*")\n            .eq("id", analysis_id)\n            .eq("user_id", user_id)\n            .single()\n            .execute()\n        )\n        return result.data\n    return await asyncio.to_thread(_op)\n\n\nasync def get_user_analyses(\n    user_id: str,\n    limit: int = 20,\n    offset: int = 0,\n    ticker: Optional[str] = None,\n    tool_name: Optional[str] = None,\n) -> list[dict]:\n    """\n    List analyses for a user with optional filtering.\n    Returns summary rows (no tool_output JSONB to keep responses small).\n    """\n    def _op():\n        from db.client import get_admin_client\n        query = (\n            get_admin_client()\n            .table("analyses")\n            # Exclude tool_output from list view — fetch full result with get_analysis_by_id\n            .select("id,user_id,ticker,tool_name,tool_params,status,"\n                    "failure_reason,elapsed_seconds,ai_interpretation,"\n                    "ai_provider,created_at,updated_at")\n            .eq("user_id", user_id)\n            .order("created_at", desc=True)\n            .range(offset, offset + limit - 1)\n        )\n        if ticker:\n            query = query.eq("ticker", ticker.upper())\n        if tool_name:\n            query = query.eq("tool_name", tool_name)\n        result = query.execute()\n        return result.data or []\n    return await asyncio.to_thread(_op)\n\n\n# ---------------------------------------------------------------------------\n# Serialisation helpers\n# ---------------------------------------------------------------------------\n\ndef _to_dict(obj: Any) -> dict:\n    """Convert a Pydantic model or plain dict to a JSON-safe dict."""\n    if isinstance(obj, BaseModel):\n        # model_dump_json() → json.loads() is the safest path:\n        # it handles Enums, datetimes, and nested models correctly.\n        return json.loads(obj.model_dump_json())\n    return obj\n\n\ndef _make_json_safe(data: Any) -> Any:\n    """Recursively ensure data is JSON-serialisable before Supabase insert."""\n    if isinstance(data, BaseModel):\n        return json.loads(data.model_dump_json())\n    if isinstance(data, dict):\n        return {k: _make_json_safe(v) for k, v in data.items()}\n    if isinstance(data, list):\n        return [_make_json_safe(i) for i in data]\n    return data\n'

